files.src/App/IUnitOfWork.cs:
using App.Repositories;

namespace App;

/// <summary>What services depend on: a repository per table and a transaction. Every repository write is committed at once; TransactionAsync only groups the code.</summary>
public interface IUnitOfWork
{
    SqlCustomerRepository Customers { get; }
    SqlCategoryRepository Categories { get; }
    SqlProductRepository Products { get; }
    SqlOrderRepository Orders { get; }
    SqlOrderLineRepository OrderLines { get; }
    SqlTagRepository Tags { get; }
    SqlProductTagRepository ProductTags { get; }
    SqlAuditLogRepository AuditLogRows { get; }

    /// <summary>Runs work with the repositories of the transaction; commits when it ends, rolls back when it throws.</summary>
    Task<T> TransactionAsync<T>(Func<IUnitOfWork, Task<T>> work);

    /// <summary>Runs work that returns nothing, in the same way.</summary>
    Task TransactionAsync(Func<IUnitOfWork, Task> work);
}

