using System.Data.Common;
using App;
using App.Common;
using App.Entities;
using App.Errors;

namespace App.Repositories;

/// <summary>Keeps audit_log rows in the database, with SQL through ADO.NET. A write joins the transaction already open, or is committed at once.</summary>
public class SqlAuditLogRepository(Db db)
{
    /// <summary>The columns every read selects.</summary>
    private const string Columns = "`at`, `message`";

    /// <summary>At most limit rows from offset, by primary key, and how many there are.</summary>
    public virtual async Task<Page<AuditLog>> ListAsync(int offset, int limit)
    {
        var items = await db.AllAsync("SELECT " + Columns + " FROM `audit_log` ORDER BY `at`, `message` LIMIT @p1 OFFSET @p2", ToEntity, limit, offset);
        var total = await db.OneAsync("SELECT COUNT(*) FROM `audit_log`", row => row.GetInt64(0));
        return new Page<AuditLog>(items, total, offset, limit);
    }

    /// <summary>The AuditLog of a row read with Columns.</summary>
    private static AuditLog ToEntity(DbDataReader row) => Fill(row, new AuditLog());

    /// <summary>Reads a row selected with Columns into entity.</summary>
    private static AuditLog Fill(DbDataReader row, AuditLog entity)
    {
        entity.At = new DateTimeOffset(row.GetDateTime(0), TimeSpan.Zero);
        entity.Message = row.GetString(1);
        return entity;
    }
}

