{
    private readonly IUnitOfWork uow = unitOfWork;

    /// <summary>Checks the values against the rules of the "product_tags" table, and the rows they point to; throws ValidationFailedException with every problem.</summary>
    private static async Task ValidateAsync(IUnitOfWork uow, Dictionary<string, object?> values, ProductTag? current)
    {
        var creating = current is null;
        var errors = new List<FieldError>();
        {
            var value = values.GetValueOrDefault("ProductId");
            if (value is null)
                if (creating || values.ContainsKey("ProductId")) errors.Add(new FieldError("product_id", "is required"));
        }
        {
            var value = values.GetValueOrDefault("TagId");
            if (value is null)
                if (creating || values.ContainsKey("TagId")) errors.Add(new FieldError("tag_id", "is required"));
        }
        {
            var productId = values.TryGetValue("ProductId", out var givenProductId) ? (long?)givenProductId : current?.ProductId;
            if (productId is not null && await uow.Products.GetByIdAsync(productId.Value) is null)
                errors.Add(new FieldError("product_id", "no Product has this key"));
        }
        {
            var tagId = values.TryGetValue("TagId", out var givenTagId) ? (long?)givenTagId : current?.TagId;
            if (tagId is not null && await uow.Tags.GetByIdAsync(tagId.Value) is null)
                errors.Add(new FieldError("tag_id", "no Tag has this key"));
        }
        if (errors.Count > 0) throw new ValidationFailedException("ProductTag", errors);
    }

