using App.Repositories;

namespace App;

/// <summary>The repositories over one Db, and its transaction.</summary>
public class SqlUnitOfWork(Db db) : IUnitOfWork
{
    public Db Db { get; } = db;
    public SqlCustomerRepository Customers { get; } = new SqlCustomerRepository(db);
    public SqlCategoryRepository Categories { get; } = new SqlCategoryRepository(db);
    public SqlProductRepository Products { get; } = new SqlProductRepository(db);
    public SqlOrderRepository Orders { get; } = new SqlOrderRepository(db);
    public SqlOrderLineRepository OrderLines { get; } = new SqlOrderLineRepository(db);
    public SqlTagRepository Tags { get; } = new SqlTagRepository(db);
    public SqlProductTagRepository ProductTags { get; } = new SqlProductTagRepository(db);
    public SqlAuditLogRepository AuditLogRows { get; } = new SqlAuditLogRepository(db);

    public async Task<T> TransactionAsync<T>(Func<IUnitOfWork, Task<T>> work)
    {
        return await work(this);
    }

    public Task TransactionAsync(Func<IUnitOfWork, Task> work) =>
        TransactionAsync<bool>(async uow =>
        {
            await work(uow);
            return true;
        });
}

