    /// <summary>A valid ProductTag that is not stored yet; n makes its unique values differ.</summary>
    public static ProductTag NewProductTag(int n)
    {
        var entity = new ProductTag();
        return entity;
    }

    /// <summary>A stored ProductTag, with the rows it points to.</summary>
    public static async Task<ProductTag> AddProductTagAsync(IUnitOfWork uow, int n)
    {
        var parent0 = await AddProductAsync(uow, n);
        var parent1 = await AddTagAsync(uow, n);
        var entity = NewProductTag(n);
        entity.ProductId = parent0.Id;
        entity.TagId = parent1.Id;
        return await uow.ProductTags.InsertAsync(entity);
