using App;

namespace App.Tests;

/// <summary>The test database: the MySQL database TEST_DATABASE_CONNECTION names, created from the schema before every test.</summary>
internal static class TestDatabase
{
    // The tables are written for one kind of database: the tests cannot fall back to SQLite
    public static readonly string? Connection = Environment.GetEnvironmentVariable("TEST_DATABASE_CONNECTION");

    /// <summary>Removes every table, so the database starts empty.</summary>
    private static readonly string[] Drop =
    [
        "SET FOREIGN_KEY_CHECKS = 0",
        "DROP TABLE IF EXISTS `audit_log`",
        "DROP TABLE IF EXISTS `product_tags`",
        "DROP TABLE IF EXISTS `tags`",
        "DROP TABLE IF EXISTS `order_lines`",
        "DROP TABLE IF EXISTS `orders`",
        "DROP TABLE IF EXISTS `products`",
        "DROP TABLE IF EXISTS `categories`",
        "DROP TABLE IF EXISTS `customers`",
        "SET FOREIGN_KEY_CHECKS = 1",
    ];

    /// <summary>Creates every table, in an order the database accepts.</summary>
    private static readonly string[] Create =
    [
        "CREATE TABLE `customers` (\n  `id` BIGINT AUTO_INCREMENT NOT NULL,\n  `email` VARCHAR(120) NOT NULL,\n  `password_hash` TEXT NOT NULL,\n  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),\n  PRIMARY KEY (`id`),\n  CONSTRAINT `uq_customers_email` UNIQUE (`email`)\n)",
        "CREATE TABLE `categories` (\n  `id` BIGINT AUTO_INCREMENT NOT NULL,\n  `name` VARCHAR(60) NOT NULL,\n  PRIMARY KEY (`id`),\n  UNIQUE (`name`)\n)",
        "CREATE TABLE `products` (\n  `id` BIGINT AUTO_INCREMENT NOT NULL,\n  `category_id` BIGINT NOT NULL,\n  `name` VARCHAR(100) NOT NULL,\n  `price` DECIMAL(10, 2) NOT NULL,\n  `status` VARCHAR(10) NOT NULL,\n  `version` INTEGER NOT NULL DEFAULT 1,\n  `deleted_at` DATETIME(6),\n  PRIMARY KEY (`id`),\n  CHECK (`price` >= 0),\n  CONSTRAINT `fk_products_category` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`)\n)",
        "CREATE INDEX `ix_products_status` ON `products` (`status`)",
        "CREATE INDEX `ix_products_category_id` ON `products` (`category_id`)",
        "CREATE TABLE `orders` (\n  `id` BIGINT AUTO_INCREMENT NOT NULL,\n  `customer_id` BIGINT NOT NULL,\n  `placed_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),\n  PRIMARY KEY (`id`),\n  FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`)\n)",
        "CREATE TABLE `order_lines` (\n  `order_id` BIGINT NOT NULL,\n  `line` INTEGER NOT NULL,\n  `product_id` BIGINT NOT NULL,\n  `quantity` INTEGER NOT NULL,\n  PRIMARY KEY (`order_id`, `line`),\n  FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE,\n  FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE RESTRICT\n)",
        "CREATE TABLE `tags` (\n  `id` BIGINT AUTO_INCREMENT NOT NULL,\n  `label` VARCHAR(30) NOT NULL,\n  PRIMARY KEY (`id`)\n)",
        "CREATE TABLE `product_tags` (\n  `product_id` BIGINT NOT NULL,\n  `tag_id` BIGINT NOT NULL,\n  PRIMARY KEY (`product_id`, `tag_id`),\n  FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE,\n  FOREIGN KEY (`tag_id`) REFERENCES `tags` (`id`) ON DELETE CASCADE\n)",
        "CREATE TABLE `audit_log` (\n  `at` DATETIME(6) NOT NULL,\n  `message` TEXT NOT NULL\n)",
    ];

    /// <summary>The test database, with every table dropped and created again; on one connection, as MySQL turns its foreign key checks off for the connection that asks.</summary>
    public static async Task<Db> OpenAsync()
    {
        if (Connection is null)
            throw new InvalidOperationException("The database tests need a disposable MySQL database: set TEST_DATABASE_CONNECTION (it is emptied)");
        var db = await Database.OpenAsync(Connection);
        foreach (var sql in Drop) await db.RunAsync(sql);
        foreach (var sql in Create) await db.RunAsync(sql);
        return db;
    }
}
